-- notification-service PostgreSQL V001 — 与 mysql/V001__init.sql **版本号与表结构对齐**。
-- 表前缀 `ntf_`（check-db-naming.js 守门）。
--
-- 转换规则（设计文档 §3 方言差异归属表 / §4.4 对照表）：
--   DATETIME / DATETIME(3)  -> TIMESTAMPTZ / TIMESTAMPTZ(3)   （§3 #3，**不是** TIMESTAMP）
--   TINYINT(1)              -> BOOLEAN                        （§3 #12）
--   BIGINT UNSIGNED         -> BIGINT                         （§3 #23，去符号，Rust 侧 u64->i64）
--   AUTO_INCREMENT          -> GENERATED BY DEFAULT AS IDENTITY（§3 #13）
--   ENUM('a','b',...)       -> VARCHAR                        （PG 原生 ENUM 需 CREATE TYPE，
--                                                              与按分号切分的执行器不兼容，改 VARCHAR）
--   MEDIUMTEXT              -> TEXT
--   列内联 COMMENT           -> 删除                            （§3 #14）
--   内联 INDEX / UNIQUE KEY  -> 独立 CREATE INDEX              （§3 #15/#16）
--   ENGINE / CHARSET / COLLATE -> 删除                          （§3 #17）
--   CURRENT_TIMESTAMP(3)    -> 原样保留                          （§3 #4，PG 16 接受）
--   JSON                    -> JSONB                          （仅写路径经 sqlx 的两列：
--                                                              envelope_json 由 outbox 库层绑
--                                                              serde_json::Value（JSONB），
--                                                              role_ids 见 V003；token-service 同款选择）
--   ON DUPLICATE KEY UPDATE -> ON CONFLICT DO NOTHING           （§3 #7/#8）
--
-- ⚠️ 关于 IDENTITY 用 BY DEFAULT 而非 ALWAYS：
--   MySQL 的 AUTO_INCREMENT **允许**显式插入 id 值，`GENERATED ALWAYS` 会拒绝。
--   用 BY DEFAULT 忠实保持 MySQL 语义（与 audit-service V001 一致）。
--
-- ⚠️ 迁移执行器是「先按 ASCII 分号切分、再剥离 `--` 注释行」，
--   因此注释里不得出现 ASCII 分号（本文件已避免）。

CREATE TABLE IF NOT EXISTS ntf_announcements (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  title           VARCHAR(200)    NOT NULL,
  body            TEXT            NOT NULL,
  publish_at      TIMESTAMPTZ     NOT NULL,
  expire_at       TIMESTAMPTZ     NULL,
  pinned          BOOLEAN         NOT NULL DEFAULT FALSE,
  popover         BOOLEAN         NOT NULL DEFAULT FALSE,
  status          VARCHAR(20)     NOT NULL,
  created_by      VARCHAR(32)     NOT NULL,
  created_at      TIMESTAMPTZ     NOT NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_ntf_announcements_status_publish
  ON ntf_announcements (status, publish_at);

CREATE TABLE IF NOT EXISTS ntf_announcement_recipients (
  announcement_id BIGINT      NOT NULL,
  scope_type      VARCHAR(16) NOT NULL,
  scope_id        VARCHAR(32) NOT NULL,
  PRIMARY KEY (announcement_id, scope_type, scope_id)
);

CREATE TABLE IF NOT EXISTS ntf_announcement_deliveries (
  announcement_id BIGINT      NOT NULL,
  user_id         VARCHAR(32) NOT NULL,
  delivered_at    TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (announcement_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_ntf_announcement_deliveries_user
  ON ntf_announcement_deliveries (user_id, announcement_id);

CREATE TABLE IF NOT EXISTS ntf_announcement_reads (
  announcement_id BIGINT      NOT NULL,
  user_id         VARCHAR(32) NOT NULL,
  read_at         TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (announcement_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_ntf_announcement_reads_user_unread
  ON ntf_announcement_reads (user_id, read_at);

-- Welcome 模板表（Phase 4.1 iam.user.created consumer 渲染欢迎站内信）
CREATE TABLE IF NOT EXISTS ntf_templates (
  code         VARCHAR(64)  NOT NULL,
  title        VARCHAR(200) NOT NULL,
  body         TEXT         NOT NULL,
  updated_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (code)
);

-- 事件幂等表
CREATE TABLE IF NOT EXISTS ntf_event_idempotency (
  event_id      VARCHAR(64)  NOT NULL,
  event_type    VARCHAR(128) NOT NULL,
  processed_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (event_id)
);

CREATE INDEX IF NOT EXISTS idx_ntf_event_idempotency_type_time
  ON ntf_event_idempotency (event_type, processed_at);

-- Outbox 表（Phase 4.3 ntf-outbox-publisher 轮询）
-- envelope_json 用 JSONB：digua_common_event::SqlOutboxRepo 绑 serde_json::Value，
-- sqlx-postgres 以 JSONB 编码，列若是 JSON 会在写路径报 42804（token-service 同款处置）。
CREATE TABLE IF NOT EXISTS ntf_outbox_events (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  event_id        CHAR(36)     NOT NULL,
  event_type      VARCHAR(128) NOT NULL,
  routing_key     VARCHAR(128) NOT NULL,
  envelope_json   JSONB        NOT NULL,
  created_at      TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  published_at    TIMESTAMPTZ(3) NULL,
  PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_ntf_outbox_event_id ON ntf_outbox_events (event_id);

CREATE INDEX IF NOT EXISTS idx_ntf_outbox_unpublished ON ntf_outbox_events (published_at, id);

-- Welcome 模板 seed（MySQL 侧 ON DUPLICATE KEY UPDATE code = code 的幂等对应用法）
INSERT INTO ntf_templates (code, title, body)
VALUES (
  'welcome',
  'Welcome to the platform, {{username}}!',
  'Hi {{username}}, welcome aboard. You have been added to {{dept_name}} on {{created_at}}. Have a great start!'
)
ON CONFLICT (code) DO NOTHING;
